        'حساب واحد ومكان واحد: فرّغ نصيًا أو اضغط أو أزل البيانات الوصفية من الملفات نفسها التي تحرّرها، وأنشئ التعليق الصوتي أو الترجمة النصية على خادم GPU نفسه.',
