          body: 'الإدخال: ملف PDF بمقاس A4 من 12 صفحة وبحجم 1.8 ميجابايت يحتوي على نص وبضعة رسوم بيانية. تُركت الإعدادات على الضبط المسبق: JPG، كل الصفحات، 150 DPI، الجودة 90. يُبلغ pdfinfo عن 12 صفحة، وهو أقل من حد 500، ويعمل pdftoppm مع ‎-r 150 -jpeg -jpegopt quality=90. تُعرض كل صفحة بأبعاد 8.27 × 150 في 11.69 × 150، أي 1240 × 1754 بكسل (2.2 ميغابكسل). يُعاد تسمية الملفات الاثني عشر من page-001.jpg إلى page-012.jpg وتُضغط في converted.zip. يجري العرض صفحةً صفحة، ويتحدد وقته أساسًا بكمية المحتوى المتجه والنص في كل صفحة؛ وتستغرق اثنتا عشرة صفحة نصية بضع ثوانٍ إجمالًا. ويعتمد حجم JPEG لكل صفحة على المحتوى: فصفحات النص ذات الخلفية البيضاء في معظمها تُضغط أفضل بكثير من رسم بياني يملأ الصفحة حتى حوافها.',
