        'يؤدي اختيار H.265 إلى استبدال المرمّز بـ libx265 وإضافة -tag:v hvc1، وهو الوسم الذي يحتاجه QuickTime وSafari للتعرّف على HEVC داخل MP4. ولا تستطيع هواتف Android الأقدم وأجهزة التلفاز الذكية وكثير من مشغّلات الويب فك ترميز H.265 إطلاقًا.',
