      whenNotToUse: 'لا تستخدم أداة القص لإزالة عدة أجزاء منفصلة من فيديو واحد؛ فهي تحتفظ بنطاق واحد بالضبط، لذا يتطلب حذف جزء من المنتصف عمليتي قص ثم دمجهما في Darkroom. ولا تتوقع أن يقع نسخ التدفقات على الإطار الدقيق؛ فإذا كان بدء القص قبل موعده بثانية أمرًا مهمًا، ففعّل خيار إعادة الترميز وتقبّل ترميزًا قصيرًا. وإذا كان هدفك الحقيقي ملفًا أصغر، فالقص لا يفيد إلا بقدر ما تحذفه؛ أما الضاغط فيغيّر معدل البت. وإذا لم يكن في الملف المرفوع تدفق فيديو، كملف M4A أُعيدت تسميته إلى MP4 مثلًا، فإن أداة القص ترفضه؛ وأدوات الصوت هي التي تتعامل مع الملفات الصوتية فقط.',
