      intro: 'ملف GIF المتحرك مجموعة من الإطارات بألوان مفهرسة، بحد أقصى 256 لونًا لكل لوحة ألوان، دون أي ضغط بين الإطارات سوى ترميز طول التكرار البسيط. ولهذا قد يزن GIF مدته بضع ثوانٍ أكثر من MP4 مدته دقيقة، ولهذا أيضًا فإن صنع GIF جيد يتعلق في الغالب باختيار العرض ومعدل الإطارات وحجم لوحة الألوان. تشغّل هذه الصفحة مسار معالجة من مرحلتين: يغيّر FFmpeg حجم الفيديو إلى العرض الذي تحدده ويأخذ منه عينات بمعدل الإطارات الذي تختاره، فيكتب GIF خامًا، ثم يعيد gifsicle تكميم لوحة الألوان إلى عدد الألوان الذي تختاره، ويضبط تأخير الإطار، ويحسّن الإطارات فلا يُخزَّن سوى البكسلات المتغيرة. والقيم الافتراضية مضبوطة لتسجيلات الشاشة: عرض 900 بكسل، و12 إطارًا في الثانية، و128 لونًا.',
