      metaTitle: 'تحويل ترميز الفيديو إلى HLS عبر الإنترنت | أداة بث تكيفي مجانية | Media Manipulator',
      metaDescription: 'أداة مجانية عبر الإنترنت لتحويل الترميز إلى HLS. حوّل MP4 وMOV وWebM وMKV إلى حزمة HLS VOD بدقات 360p/480p/720p مع ترجمات ولوحات قصة اختيارية.',
      ogTitle: 'تحويل ترميز الفيديو إلى HLS عبر الإنترنت',
      ogDescription: 'أنشئ حزمة HLS تكيفية (master.m3u8 + قوائم تشغيل النسخ + مقاطع ‎.ts) من أي فيديو، مجانًا وفي متصفحك.',
      intro: 'يقدّم HTTP Live Streaming الفيديو كقائمة تشغيل من مقاطع قصيرة بعدة مستويات جودة، فيستطيع المشغّل البدء بسرعة والتنقل بين الدرجات مع تغيّر الاتصال. وإنتاج هذه الحزمة يدويًا يعني ترميز كل نسخة بإطارات مفتاحية متوافقة، وتقطيعها، وكتابة قائمة تشغيل رئيسية تصف كل نسخة بشكل صحيح. تتولى هذه الصفحة المهمة كلها: تفحص الملف المرفوع، وتعرض درجات السلّم التي يسمح بها مصدرك وباقتك، وترمّز كل درجة باستخدام libx264 وAAC إلى مقاطع MPEG-TS مدة كل منها 2 ثانية، وتضيف اختياريًا ترجمة نصية من أداة التفريغ Whisper الخاصة بنا، وصفيحة صور للوحات المصغرات، وقائمة تشغيل إطارات I للتنقل، وتجمع كل ذلك في ملف tar.gz أو zip يمكنك فكّه على أي استضافة ثابتة.',
      whatItDoes: [
        'يفحص المصدر باستخدام ffprobe ويسرد درجات السلّم: 144p و240p و360p و480p و720p و1080p و2160p، ولا تُفعَّل كل منها إلا إذا كان المصدر بالارتفاع الكافي وسمحت باقتك بها.',
        'يرمّز كل درجة محددة باستخدام libx264 بملف التعريف High والمستوى 4.1 وصوت AAC ستيريو بتردد 48 kHz، إلى مقاطع ‎.ts مدة كل منها 2 ثانية مع إطار مفتاحي عند كل حد بين المقاطع.',
        'يكتب hls/master.m3u8 مع BANDWIDTH وRESOLUTION وFRAME-RATE وCODECS لكل نسخة، إضافةً إلى ملف index.m3u8 لكل درجة.',
        'يفرّغ الصوت اختياريًا باستخدام Whisper إلى مسار WebVTT، ويترجمه إلى ما يصل إلى 3 لغات إضافية بنموذج محلي، ويربط كلًّا منها كنسخة ترجمة نصية في القائمة الرئيسية.',
        'يعرض اختياريًا صفيحة صور للوحات المصغرات مع فهرس WebVTT لمصغرات شريط التنقل، ويحاول دائمًا إضافة قائمة تشغيل لإطارات I فقط بدقة 240p.',
        'يحزّم المجلد مع README.txt وreport.json في ملف tar.gz (أو zip) ويعطيك رابط تنزيل موقّعًا مسبقًا.',
      ],
