      intro: 'يمرّر ترميم الصور بالذكاء الاصطناعي صورة واحدة عبر مسار معالجة قابل للتهيئة من ثمانية نماذج كحد أقصى، ويعرض كل نتيجة بجانب الأصل. تزيل مرحلة تنظيف مسبق تحافظ على الأمانة (FBCNN لعيوب JPEG، وSCUNet للتشويش، وNAFNet لتمويه الحركة) التدهور دون اختلاق تفاصيل؛ ثم تكبّر المكبّرات العامة (Real-ESRGAN وSwinIR وHAT) الصورة 2x أو 4x؛ ويعيد تحسين الوجوه الاختياري (GFPGAN وCodeFormer) بناء الوجوه. التنظيف المسبق غير توليدي: فهو يرشّح الإشارة الموجودة فعلًا. أما تحسين الوجوه فتوليدي: إذ يركّب تفاصيل معقولة، ويجب ألا يُعامل كاستعادة أمينة للمصدر. ويعمل كل نموذج على خادم GPU الخاص بنا.',
