        'ينظّف الصورة مسبقًا أولًا إن أردت، دائمًا بالترتيب FBCNN ثم SCUNet ثم NAFNet، ويعمل كل نموذج على إخراج سابقه؛ وتصبح الصورة المنظّفة الأساس الذي يبدأ منه كل نموذج لاحق.',
