        'لا يُقبل سوى المعاملين 2 و4 وأسماء النماذج الثلاثة realesrgan-x4plus وrealesrgan-x4plus-anime وrealesr-animevideov3؛ ويُرفض أي شيء آخر قبل بدء المهمة.',
        'يشغّل 2x شبكة x4 نفسها بنصف المعامل. وتحمل الاستمارة ملاحظة بأن 2x قد يبدو مقتطعًا أو مقرّبًا قليلًا في بعض الصور، وهو ما لوحظ على الخادم مع صورة بأبعاد 640 x 360؛ ولا تخفي واجهة API ذلك عمدًا بتشغيل 4x ثم التصغير.',
        'لأن مسار الذكاء الاصطناعي يتجاوز ImageMagick ونسخ exiftool، فإن إعدادات الجودة وتغيير الحجم والمرشحات والبيانات الوصفية في الاستمارة لا تؤثر هنا، ولا يحمل ملف PNG أي بيانات EXIF من الأصل.',
        'يزداد عدد البكسلات بمربع المعامل: 4x يعني 16 ضعفًا من البكسلات و2x يعني 4 أضعاف. وحجم بيانات RGB غير المضغوطة للإخراج هو العرض x الارتفاع x 3 بايت، وهذا ما يحدّ أقصى حجم يمكن أن يبلغه ملف PNG.',
        'لا يوجد على الخادم حد لأبعاد المدخلات خاص بهذه العملية سوى حد حجم الملف الواحد في باقتك؛ والمدخلات الكبيرة جدًا تستغرق وقتًا أطول فحسب، مربعًا تلو الآخر.',
