          body: 'المدخل: صورة مصغّرة لمنظر طبيعي بصيغة JPEG، حجمها 92 كيلوبايت وأبعادها 640 x 360. تُركت الإعدادات على الإعداد المسبق: 4x، ونموذج الصور الفوتوغرافية، وإخراج PNG. يشغّل الخادم realesrgan-ncnn-vulkan -n realesrgan-x4plus -s 4 -t 0 -f png ويكتب ملف converted.png بأبعاد 2560 x 1440 بكسل، أي 16 ضعف البكسلات الأصلية البالغة 230,400 بكسل. ويبلغ حجم الإخراج غير المضغوط 2560 x 1440 x 3 = 11 ميجابايت من بيانات RGB، ويأتي ملف PNG أصغر من ذلك بحسب مقدار السماء والألوان المسطحة فيه، فتوقّع عدة ميجابايتات من مدخل حجمه 92 كيلوبايت. وتستغرق معالجة GPU للمربعات المختارة تلقائيًا ثوانيَ معدودة لإخراج بهذا الحجم؛ بينما يستهلك ترميز PNG وتنزيل ملف من عدة ميجابايتات حصة ملحوظة من الوقت الإجمالي.',
