      whenNotToUse: 'لا تكبّر صورة كبيرة وحادة أصلًا: فصورة بدقة 12 ميجابكسل بمعامل 4x تصبح ملف PNG بدقة 192 ميجابكسل بطيء الإنتاج، يبلغ حجمه مئات الميجابايتات دون ضغط، ولا يكسب أي تحسن مرئي. ولا تعتمد عليه في الوجوه أو النصوص أو الشعارات أو أي شيء يجب الحفاظ فيه على الأصل بدقة، لأن التفاصيل المضافة متوقَّعة لا مستعادة، وقد يظهر النص الصغير بحروف تبدو معقولة لكنها خاطئة. ولا تُصلح الدقةُ ضبابيةَ الحركة الشديدة ولا خطأ التركيز البؤري. وإذا كنت تحتاج فقط إلى حجم محدد بالبكسل من أصل أكبر، فأداة تغيير الحجم العادية أسرع وأرخص.',
