          body: 'المُدخل: ملف JPEG بحجم 3.5 MB وأبعاد 4000 x 3000 بكسل من هاتف، فيه 14 شخصًا. الإعدادات: تمويه، ووضع الاختيار «الكل»، دون اكتشاف مسبق. يشغّل السكربت YuNet على الإطار الكامل البالغ 12 ميجابكسل؛ فوجه مربعه 300 x 360 بكسل يُوسَّع بنسبة 18 بالمئة إلى نحو 408 x 490 ويُموَّه بنواة غاوسية قدرها 163 px ‏(490 / 3، مقرّبة إلى عدد فردي)، فيتحول إلى بقعة بلا ملامح. ويحصل وجه بحجم 60 px في الصف الخلفي على نواة 27 px، وهذا يكفي لإزالة الملامح بذلك الحجم. والناتج ملف JPG بأبعاد 4000 x 3000 يكتبه OpenCV، ولا يبتعد حجمه عادةً عن حجم الأصل بأكثر من بضع مئات من الكيلوبايت. يستغرق الاكتشاف والتمويه بضع ثوانٍ؛ أما رفع ملف بحجم 3.5 MB فيستغرق عادةً وقتًا أطول.',
