          body: 'المُدخل: ملف PNG بحجم 2.3 MB وأبعاد 1920 x 1080 لمصباح على طاولة مع كابل وملصق سعر. ارسم مربعين: أحدهما فوق الكابل (نحو 5% في 30%) والآخر فوق الملصق (نحو 8% في 6%). يُحوَّل كلاهما نقطيًا إلى القناع نفسه بأبعاد 1920 x 1080، فتعالج مرحلة إعادة رسم واحدة المنطقتين معًا. اختر PNG صيغةً للإخراج لتجنب عيوب JPEG في المناطق المملوءة؛ والنتيجة ملف PNG بأبعاد 1920 x 1080، بصيغة RGB معتمة لأن Pillow يحوّل المُدخل إلى RGB قبل إعادة الرسم. وبدقة 2 ميجابكسل تكون مرحلة GPU سريعة، ويذهب معظم الوقت الفعلي في الرفع وكتابة ملف PNG.',
