      whenNotToUse: 'لا تستخدم إعادة الرسم على عنصر يغطي جزءًا كبيرًا من الإطار، أو يقع أمام وجه، أو يتداخل مع نص مقروء، أو يقطع نمطًا منتظمًا مثل الطوب أو البلاط أو لوحة المفاتيح: إذ يضطر النموذج إلى اختلاق بنية، فتبدو النتيجة ملطخة أو مكررة. وهي أيضًا الأداة الخطأ حين تريد الحفاظ على ملف PNG شفاف سليمًا، لأن السكربت يسطّح المُدخل إلى RGB، وحين يجب أن يكون التعديل أمينًا من الناحية الجنائية، لأن المنطقة المملوءة محتوى مُولَّد. ولاستبدال الخلفية كاملة استخدم أداة إزالة الخلفية؛ أما الوجوه التي تحتاج إلى إخفاء فحسب، فأداة تمويه الوجوه أنسب.',
