      privacyNote: 'تُخزَّن صورتك في uploads/<jobId>/ على خادمنا؛ ويُكتب قناع المستطيلات كملف PNG مؤقت في المجلد المؤقت للخادم ويُحذف فور انتهاء سكربت إعادة الرسم؛ وتذهب الصورة المملوءة إلى outputs/<jobId>/. وتُحفظ إحداثيات المستطيلات في خيارات المهمة لإمكان إعداد التقارير عنها. يعمل LaMa على وحدة GPU في الجهاز نفسه، ولا يذهب أي جزء من الصورة إلى مزوّد خارجي. وتُلخَّص كل صورة مرفوعة، بما فيها هذه، مرة واحدة أيضًا بخطوة تحليل آلية على خادمنا باستخدام نموذج رؤية محلي، ويبقى ذلك الملخص مع المهمة. ولا يحمل الناتج أي بيانات EXIF لأن عمليات الذكاء الاصطناعي تتخطى نسخ البيانات الوصفية. تُحفظ الملفات 24 ساعة للزوار؛ ومع حساب مجاني تختار مدة بين 24 ساعة وسنتين.',
